    public static List<CardDefinition> starterDeck() {
        Map<Integer, CardDefinition> all = all();
        List<CardDefinition> result = new ArrayList<>();
        for (int id : STARTER_IDS) {
            CardDefinition card = all.get(id);
            if (card != null) result.add(card);
        }
        return result;
    }

    public static List<Integer> starterIds() {
        List<Integer> ids = new ArrayList<>();
        for (int id : STARTER_IDS) ids.add(id);
        return Collections.unmodifiableList(ids);
    }
